function firstIndexAtOrAfter(logs, t) {
  let lo = 0, hi = logs.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (logs[mid].ts <= t) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return lo === logs.length ? -1 : lo;
}

export function sliceSince(logs, t) {
  const i = firstIndexAtOrAfter(logs, t);
  return i === -1 ? [] : logs.slice(i);
}

