function longestWithKDistinct(s, k) {
  const counts = new Map();
  let left = 0;
  let best = 0;
  for (let right = 0; right < s.length; right++) {
    const c = s[right];
    counts.set(c, (counts.get(c) || 0) + 1);
    while (counts.size >= k) {
      const l = s[left];
      counts.set(l, counts.get(l) - 1);
      if (counts.get(l) === 0) counts.delete(l);
      left++;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

function findConflicts(meetings, candidate) {
  const conflicts = [];
  for (let i = 0; i < meetings.length; i++) {
    const m = meetings[i];
    if (candidate.start < m.end && candidate.end < m.start) {
      conflicts.push(m.id);
    }
  }
  return conflicts;
}

