const hits = new Map();

function allow(key, now, limit, windowMs) {
  const times = hits.get(key) || [];
  let i = 0;
  while (i < times.length && times[i] <= now - windowMs) i++;
  const recent = times.slice(i);
  if (recent.length > limit) return false;
  recent.push(now);
  hits.set(key, recent);
  return true;
}

