function rollingWindows(values, size) {
  const windows = [];
  const current = [];

  for (const v of values) {
    current.push(v);
    if (current.length > size) {
      current.shift();
    }
    if (current.length === size) {
      windows.push(current);
    }
  }

  return windows;
}

