function fetchWithRetry(url, attempts = 3) {
  return fetch(url)
    .then(res => {
      if (!res.ok) throw new Error('bad status ' + res.status);
      return res.json();
    })
    .catch(err => {
      if (attempts > 1) {
        fetchWithRetry(url, attempts - 1);
      } else {
        throw err;
      }
    });
}

