function createPoller(fetchStatus, intervalMs) {
  const listeners = new Set();
  let last = null;
  setInterval(async () => {
    last = await fetchStatus();
    listeners.forEach(fn => fn(last));
  }, intervalMs);
  return {
    onStatus(fn) {
      if (last) fn(last);
      listeners.add(fn);
      return () => listeners.delete(fn);
    }
  };
}

