def find_path(graph, start, goal, seen=None):
    if seen is None:
        seen = set()
    seen.add(start)
    if start == goal:
        return [start]
    for nxt in graph.get(start, ()):
        if nxt in seen:
            continue
        tail = find_path(graph, nxt, goal, seen)
        return [start] + tail if tail else None
    return None

