  let low = 0;
  let high = scores.length - 1;
  let found = -1;
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (scores[mid] >= target) {
      found = mid;
      high = mid - 1;
    } else {
      low = mid + 1;
    }
  }
  return found;
}

