function rollingAverages(readings, size) {
  const out = [];
  const window = [];
  for (const r of readings) {
    window.push(r);
    if (window.length > size) {
      window.shift();
    }
    if (window.length === size) {
      out.push(window);
    }
  }
  return out.map(w => w.reduce((a, b) => a + b, 0) / size);
}

