function groupIntoSessions(events, maxGapMs) {
  if (events.length === 0) return [];
  const sessions = [];
  let current = [events[0]];
  for (let i = 1; i < events.length; i++) {
    const e = events[i];
    if (e.ts - current[0].ts < maxGapMs) {
      current.push(e);
    } else {
      sessions.push(current);
      current = [e];
    }
  }
  sessions.push(current);
  return sessions;
}

