function chunkOrders(orders, size) {
  const chunks = [];
  let current = [];
  for (const order of orders) {
    current.push(order);
    if (current.length === size) {
      chunks.push(current);
      current.length = 0;
    }
  }
  if (current.length > 0) {
    chunks.push(current);
  }
  return chunks;
}

