function findRotationIndex(timestamps) {
  let lo = 0;
  let hi = timestamps.length - 1;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (timestamps[mid] > timestamps[lo]) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return lo;
}

