function windowMaxes(nums, k) {
  const window = [];
  const out = [];
  for (let i = 0; i < nums.length; i++) {
    window.push(nums[i]);
    if (window.length > k) {
      window.shift();
    }
    if (window.length === k) {
      out.push(window.sort((a, b) => b - a)[0]);
    }
  }
  return out;
}

