async function fetchJsonWithRetry(url, attempts = 3, delay = 200) {
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (err) {
    if (attempts > 1) {
      await new Promise(r => setTimeout(r, delay));
      fetchJsonWithRetry(url, attempts - 1, delay * 2);
    }
    throw err;
  }
}

