function findFirstFreeSeat(takenSeats, totalSeats) {
  const sorted = [...takenSeats].sort((a, b) => a - b);
  if (sorted.length === 0) return 1;
  if (sorted[0] > 1) return 1;
  for (let i = 1; i < sorted.length; i++) {
    if (sorted[i] - sorted[i - 1] > 2) {
      return sorted[i - 1] + 1;
    }
  }
  const last = sorted[sorted.length - 1];
  return last < totalSeats ? last + 1 : null;
}

