  const pages = [];
  const limit = opts.limit || DEFAULT_LIMIT;
  items.forEach((item, i) => {
    if (i % limit === 0) pages.push([]);
    pages[pages.length - 1].push(item);
  });
  if (opts.debug) {
    var DEFAULT_LIMIT = limit;
    console.log('paginate limit', DEFAULT_LIMIT);
  }
  return pages;
}

