def resolve_config(defaults, user_settings):
    resolved = {}
    for key in defaults:
        resolved[key] = user_settings.get(key) or defaults[key]
    for key in user_settings:
        if key not in resolved:
            resolved[key] = user_settings[key]
    return resolved


