function chunk(items, size) {
  const out = [];
  let buffer = [];
  for (const item of items) {
    buffer.push(item);
    if (buffer.length === size) {
      out.push(buffer);
      buffer.length = 0;
    }
  }
  if (buffer.length) out.push(buffer);
  return out;
}

