def best_k_day_total(readings, k):
    if k > len(readings):
        return None
    window = sum(readings[:k])
    best = window
    for i in range(1, len(readings) - k):
        window += readings[i + k - 1] - readings[i - 1]
        if window > best:
            best = window
    return best

MISSING = object()

class Config:
    def __init__(self, defaults):
        self._defaults = defaults
        self._overrides = {}

    def set(self, key, value):
        self._overrides[key] = value

    def get(self, key):
        value = self._overrides.get(key, MISSING)
        if value == MISSING:
            return self._defaults.get(key)
        return value
